input.script:
services = list_services({})
counts = for svc in services {
    result = boundary retry 2 {
        return search_logs({ service: svc, level: "ERROR", page: 1 })
    } catch err {
        return fail("SEARCH_FAILED", svc + ": " + err.code + ": " + err.message)
    }
    first = result.items[0] if result.items != [] else null
    last = result.items[list.length(result.items) - 1] if result.items != [] else null
    return {
        service: svc,
        total_errors: result.total_items,
        total_pages: result.total_pages,
        first_ts: first.ts if first != null else null,
        last_ts: last.ts if last != null else null
    }
}
return counts

pages = for page in list.range(1, 3) {
    result = boundary retry 2 {
        return search_logs({ service: "payments", level: "ERROR", page })
    } catch err {
        return fail("SEARCH_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
logs = fold acc = [] for page in pages { return acc + page }
entries = for item in logs {
    return { ts: item.ts, message: item.message }
}
deploys = boundary retry 2 { return get_deploys({ service: "payments" }) } catch err {
    return fail("DEPLOYS_FAILED", err.code + ": " + err.message)
}
owner = boundary retry 2 { return get_service_owners({ service: "payments" }) } catch err {
    return fail("OWNER_FAILED", err.code + ": " + err.message)
}
return { errors: entries, deploys, owner }
